    "questionAr": "قطعة مستقيمة من لولب DNA مزدوج تحتوي على $N = 5$ لَفَّة حلزونية كاملة. احسب عدد أزواج القواعد النيتروجينية والطول الفعلي لهذه القطعة بوحدة النانومتر ($\\text{nm}$، علماً بأن اللفة الكاملة طولها $3.4\\text{ nm}$ وتضم $10$ أزواج من القواعد).",
